//! Which drawing engines each MODEL handles reliably — measured, not assumed.
//! `visual_capabilities.json` is generated by `scripts/build-capability-matrix.ts`
//! from the Rust replays of the real-model figure evals (successes / outputs
//! per model and engine, counting only rejections OF THE FIGURE).
//!
//! An engine is unreliable for a model only with clear evidence: the upper
//! end of the 95 % Wilson interval of its success rate is still below the
//! threshold. Sparse data (a 5/6) never restricts anything. The router uses
//! it two ways (see `notebook_service::generation`): the generator is told
//! which engines to avoid when another one can draw the same content, and a
//! block drawn with an unreliable engine goes straight to the escalation
//! model when one is configured.

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

#[derive(Debug, Clone, Copy, Deserialize)]
pub struct EngineStat {
    pub n: u32,
    pub ok: u32,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CapabilityMatrix {
    pub threshold: f64,
    pub min_samples: u32,
    pub models: HashMap<String, HashMap<String, EngineStat>>,
}

pub fn matrix() -> &'static CapabilityMatrix {
    static M: OnceLock<CapabilityMatrix> = OnceLock::new();
    M.get_or_init(|| serde_json::from_str(include_str!("visual_capabilities.json")).expect("visual_capabilities.json is valid"))
}

/// Words that mark a review finding as being about the FIGURE (its engine,
/// intent or coherence) — same list as `aboutFigure` in
/// `scripts/build-capability-matrix.ts`, plus the critic's word "figura".
const FIGURE_WORDS: [&str; 22] = [
    "visualaid", "visualintent", "espacial", "curvatura", "figura", "sequence_strip", "diagram_spec", "mermaid", "solid_model", "surface_3d",
    "explorable_model", "topology_flow", "interactive_module", "declarative_svg", "conceptual_matrix", "trayectoria", "geodésica",
    "molecule_3d", "algebraic_structure", "instrument", "illustration_kit", "code_figure",
];

pub fn is_figure_feedback(finding: &str) -> bool {
    let f = finding.to_lowercase();
    FIGURE_WORDS.iter().any(|w| f.contains(w))
}

/// Base engine name of a block's figure (`interactive_module`, not `:relation_explorer`).
pub fn figure_engine(block: &crate::domain::notebook::GeneratedSectionBlock) -> Option<&'static str> {
    use crate::domain::notebook::GeneratedSectionBlock as B;
    let visual = match block {
        B::DeclarativeVisualDiagram { visual_aid, .. } => Some(visual_aid),
        B::AnchoredMicroTheory { visual_aid, .. }
        | B::BranchingScenarioChallenge { visual_aid, .. }
        | B::HeuristicErrorAudit { visual_aid, .. }
        | B::InteractivePredictionGate { visual_aid, .. }
        | B::HandsOnMission { visual_aid, .. } => visual_aid.as_ref(),
        _ => None,
    }?;
    Some(crate::domain::visual_routing::engine_keys(visual).0)
}

/// Upper bound of the 95 % Wilson score interval for `ok` successes in `n`.
pub fn wilson_upper(ok: u32, n: u32) -> f64 {
    if n == 0 {
        return 1.0;
    }
    let (n, p, z) = (n as f64, ok as f64 / n as f64, 1.96_f64);
    let denom = 1.0 + z * z / n;
    let centre = p + z * z / (2.0 * n);
    let margin = z * ((p * (1.0 - p) + z * z / (4.0 * n)) / n).sqrt();
    ((centre + margin) / denom).min(1.0)
}

impl CapabilityMatrix {
    /// Is `engine` (base name, e.g. `solid_model`) clearly unreliable for `model`?
    pub fn unreliable(&self, model: &str, engine: &str) -> bool {
        self.models
            .get(model)
            .and_then(|m| m.get(engine))
            .is_some_and(|s| s.n >= self.min_samples && wilson_upper(s.ok, s.n) < self.threshold)
    }

    /// Every engine clearly unreliable for `model`, sorted.
    pub fn unreliable_engines(&self, model: &str) -> Vec<String> {
        let mut v: Vec<String> = self
            .models
            .get(model)
            .map(|m| m.keys().filter(|e| self.unreliable(model, e)).cloned().collect())
            .unwrap_or_default();
        v.sort();
        v
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn m(cells: &[(&str, u32, u32)]) -> CapabilityMatrix {
        CapabilityMatrix {
            threshold: 0.85,
            min_samples: 3,
            models: [("flash".to_string(), cells.iter().map(|(e, n, ok)| (e.to_string(), EngineStat { n: *n, ok: *ok })).collect())].into(),
        }
    }

    #[test]
    fn only_clear_evidence_marks_an_engine_unreliable() {
        let matrix = m(&[("diagram_spec", 6, 5), ("solid_model", 20, 9), ("mermaid", 2, 0), ("sequence_strip", 40, 25)]);
        assert!(!matrix.unreliable("flash", "diagram_spec"), "5/6 is noise, not evidence");
        assert!(matrix.unreliable("flash", "solid_model"), "9/20 is clearly below 85 %");
        assert!(!matrix.unreliable("flash", "mermaid"), "too few samples to judge");
        assert!(matrix.unreliable("flash", "sequence_strip"), "25/40: the interval tops out under 85 %");
        assert!(!matrix.unreliable("opus", "solid_model"), "an unmeasured model is never restricted");
        assert_eq!(matrix.unreliable_engines("flash"), vec!["sequence_strip".to_string(), "solid_model".to_string()]);
    }

    #[test]
    fn figure_findings_are_told_apart_from_the_rest() {
        assert!(is_figure_feedback("bloque 0: el concepto es una CURVATURA y lo dibujaste con interactive_module:relation_explorer"));
        assert!(is_figure_feedback("la figura contradice la regla"));
        assert!(!is_figure_feedback("intuitiveHook (40) + analogyBoundary (28) suman 117 palabras"));
    }

    #[test]
    fn the_shipped_matrix_loads() {
        let real = matrix();
        assert!(real.threshold > 0.5 && real.min_samples >= 1);
        assert!(!real.models.is_empty(), "built from the evals");
    }
}
